#   if 가 넷이고 상수가 흩어져 있다

public enum MemberLevel {
    NORMAL(0, 0.0),
    SILVER(1, 0.05),
    GOLD(2, 0.10),
    VIP(3, 0.15);

    private final int code;
    private final double discountRate;

    public static MemberLevel of(int code) {
        return Arrays.stream(values())
                .filter(l -> l.code == code)
                .findFirst()
                .orElseThrow(() ->
                        new IllegalArgumentException("존재하지 않는 회원 등급입니다."));
    }
}

public static int calculate(int price, int level) {
    return (int) (price * (1 - MemberLevel.of(level).getDiscountRate()));
}

